using System.Globalization;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using YamlDotNet.Core;
using YamlDotNet.RepresentationModel;

namespace IceScreenTouch.Api.Tests;

/// <summary>
/// docs/api/openapi.yaml (hand-written, the source of truth) against the document the server embeds and serves
/// (src/IceScreenTouch.Api/openapi.json, generated by tools/openapi_to_json.py), and against the routes and error codes of the
/// server. YamlDotNet is a test-only dependency.
/// </summary>
public partial class OpenApiSpecTests
{
    internal const string RegenerateHint = "Run from the repository root: uv run --with pyyaml python tools/openapi_to_json.py";

    private static readonly string[] HttpMethods = ["get", "put", "post", "delete", "options", "head", "patch", "trace"];

    [Fact]
    public void TheEmbeddedJsonIsTheYamlSpecification()
    {
        var yaml = SpecFiles.LoadYaml();
        var json = SpecFiles.LoadEmbeddedJson();

        var differences = new List<string>();
        Compare("$", yaml, json, differences);

        Assert.True(
            differences.Count == 0,
            $"docs/api/openapi.yaml and the embedded src/IceScreenTouch.Api/openapi.json differ ({differences.Count} difference(s)). {RegenerateHint}\n"
            + string.Join('\n', differences.Take(10)));
    }

    [Fact]
    public void TheSpecificationPathsAndMethodsAreTheServersRoutes()
    {
        var spec = SpecFiles.LoadYaml();
        var inSpec = SpecOperations(spec).Order(StringComparer.Ordinal).ToArray();
        var registered = SpecFiles.RegisteredRoutes().Order(StringComparer.Ordinal).ToArray();

        var missingInSpec = registered.Except(inSpec).ToArray();
        var unknownToServer = inSpec.Except(registered).ToArray();

        Assert.True(
            missingInSpec.Length == 0 && unknownToServer.Length == 0,
            $"the spec and the server's routes differ.\nregistered but not in docs/api/openapi.yaml: [{string.Join(", ", missingInSpec)}]\nin docs/api/openapi.yaml but not registered: [{string.Join(", ", unknownToServer)}]");
    }

    [Fact]
    public void EveryOperationHasAnIdAndASummaryAndOperationIdsAreUnique()
    {
        var spec = SpecFiles.LoadYaml();
        var ids = new List<string>();
        foreach (var (path, item) in spec["paths"]!.AsObject())
        {
            foreach (var (method, operation) in item!.AsObject())
            {
                var where = $"{method.ToUpperInvariant()} {path}";
                var id = operation!["operationId"]?.GetValue<string>();
                Assert.False(string.IsNullOrWhiteSpace(id), $"{where} has no operationId");
                Assert.False(string.IsNullOrWhiteSpace(operation["summary"]?.GetValue<string>()), $"{where} has no summary");
                Assert.NotNull(operation["responses"]);
                ids.Add(id!);
            }
        }

        Assert.Equal(ids.Count, ids.Distinct(StringComparer.Ordinal).Count());
    }

    [Fact]
    public void TheProblemCodesAreTheServersErrorCodes()
    {
        var spec = SpecFiles.LoadYaml();
        var enumValues = spec["components"]!["schemas"]!["Problem"]!["properties"]!["code"]!["enum"]!
            .AsArray().Select(n => n!.GetValue<string>()).ToArray();
        var serverCodes = typeof(ApiErrorCodes)
            .GetFields(BindingFlags.Public | BindingFlags.Static)
            .Where(f => f is { IsLiteral: true } && f.FieldType == typeof(string))
            .Select(f => (string)f.GetRawConstantValue()!)
            .ToArray();

        Assert.Equal(serverCodes.Order(StringComparer.Ordinal), enumValues.Order(StringComparer.Ordinal));
        Assert.Equal(enumValues.Length, enumValues.Distinct(StringComparer.Ordinal).Count());
    }

    [Fact]
    public void TheProblemTableHasTheRightStatusForEveryCode()
    {
        var spec = SpecFiles.LoadYaml();
        var description = spec["components"]!["schemas"]!["Problem"]!["description"]!.GetValue<string>();
        var rows = ProblemRow().Matches(description).Select(m => (Code: m.Groups[1].Value, Status: int.Parse(m.Groups[2].Value, CultureInfo.InvariantCulture))).ToArray();
        var enumValues = spec["components"]!["schemas"]!["Problem"]!["properties"]!["code"]!["enum"]!
            .AsArray().Select(n => n!.GetValue<string>()).ToArray();

        Assert.Equal(enumValues.Order(StringComparer.Ordinal), rows.Select(r => r.Code).Order(StringComparer.Ordinal));
        foreach (var (code, status) in rows)
        {
            Assert.Equal(ApiErrorCodes.StatusOf(code), status);
        }
    }

    [Fact]
    public void TheVersionAndTheApiVersionAgree()
    {
        var spec = SpecFiles.LoadYaml();
        var version = spec["info"]!["version"]!.GetValue<string>();

        Assert.Equal("3.1.0", spec["openapi"]!.GetValue<string>());
        Assert.StartsWith($"{StreamEvent.Ready().Api}.", version, StringComparison.Ordinal); // the major number is the api of the ready event and of /v1/status
        Assert.Equal("MIT", spec["info"]!["license"]!["identifier"]!.GetValue<string>());
        Assert.Contains("http://127.0.0.1:{port}", spec["servers"]![0]!["url"]!.GetValue<string>(), StringComparison.Ordinal);
    }

    [Fact]
    public void EveryInternalReferenceResolves()
    {
        var spec = SpecFiles.LoadYaml();
        var broken = new List<string>();
        Walk(spec, "#", (node, pointer) =>
        {
            if (node is JsonObject obj && obj["$ref"] is JsonValue reference && reference.TryGetValue<string>(out var target) && target.StartsWith('#'))
            {
                if (!Resolve(spec, target))
                {
                    broken.Add($"{pointer}: {target}");
                }
            }
        });

        Assert.True(broken.Count == 0, "unresolved references: " + string.Join("; ", broken));
    }

    [Fact]
    public void OnlyTheWebSocketAndTheSpecificationAreWithoutASecurityRequirement()
    {
        var spec = SpecFiles.LoadYaml();
        Assert.Single(spec["security"]!.AsArray());
        Assert.NotNull(spec["components"]!["securitySchemes"]!["bearerAuth"]);

        var open = new List<string>();
        foreach (var (path, item) in spec["paths"]!.AsObject())
        {
            foreach (var (method, operation) in item!.AsObject())
            {
                if (operation!["security"] is JsonArray { Count: 0 })
                {
                    open.Add($"{method.ToUpperInvariant()} {path}");
                }
            }
        }

        Assert.Equal(["GET /v1/openapi.json", "GET /v1/stream"], open.Order(StringComparer.Ordinal));
    }

    /// <summary>"GET /v1/status" for every operation of the spec.</summary>
    internal static IEnumerable<string> SpecOperations(JsonNode spec)
    {
        foreach (var (path, item) in spec["paths"]!.AsObject())
        {
            foreach (var (member, _) in item!.AsObject())
            {
                if (HttpMethods.Contains(member, StringComparer.Ordinal))
                {
                    yield return $"{member.ToUpperInvariant()} {path}";
                }
            }
        }
    }

    // ---- Comparison of the YAML and the JSON (with the types of the values) -----------------------------------------

    private static void Compare(string path, JsonNode? yaml, JsonNode? json, List<string> differences)
    {
        var (a, b) = (yaml?.GetValueKind(), json?.GetValueKind());
        if (yaml is null && json is null)
        {
            return;
        }

        if (yaml is null || json is null || a != b)
        {
            differences.Add($"{path}: yaml has {Describe(yaml)}, json has {Describe(json)}");
            return;
        }

        switch (a)
        {
            case JsonValueKind.Object:
                var (ya, ja) = (yaml.AsObject(), json.AsObject());
                foreach (var (key, value) in ya)
                {
                    if (!ja.TryGetPropertyValue(key, out var other))
                    {
                        differences.Add($"{path}.{key}: only in yaml");
                        continue;
                    }

                    Compare($"{path}.{key}", value, other, differences);
                }

                foreach (var (key, _) in ja)
                {
                    if (!ya.ContainsKey(key))
                    {
                        differences.Add($"{path}.{key}: only in json");
                    }
                }

                break;
            case JsonValueKind.Array:
                var (yl, jl) = (yaml.AsArray(), json.AsArray());
                if (yl.Count != jl.Count)
                {
                    differences.Add($"{path}: yaml has {yl.Count} items, json has {jl.Count}");
                    break;
                }

                for (var i = 0; i < yl.Count; i++)
                {
                    Compare($"{path}[{i}]", yl[i], jl[i], differences);
                }

                break;
            case JsonValueKind.String:
                if (!string.Equals(yaml.GetValue<string>(), json.GetValue<string>(), StringComparison.Ordinal))
                {
                    differences.Add($"{path}: the strings differ");
                }

                break;
            case JsonValueKind.Number:
                if (NumberOf(yaml) != NumberOf(json))
                {
                    differences.Add($"{path}: yaml has {yaml.ToJsonString()}, json has {json.ToJsonString()}");
                }

                break;
        }
    }

    // A number node holds a long (built from the YAML) or a JsonElement (parsed from the JSON); both go through the text.
    private static double NumberOf(JsonNode node) => double.Parse(node.ToJsonString(), NumberStyles.Float, CultureInfo.InvariantCulture);

    private static string Describe(JsonNode? node) => node is null ? "nothing" : $"{node.GetValueKind()} {Truncate(node.ToJsonString())}";

    private static string Truncate(string text) => text.Length <= 60 ? text : text[..60] + "...";

    private static void Walk(JsonNode? node, string pointer, Action<JsonNode, string> visit)
    {
        if (node is null)
        {
            return;
        }

        visit(node, pointer);
        switch (node)
        {
            case JsonObject obj:
                foreach (var (key, value) in obj)
                {
                    Walk(value, $"{pointer}/{key}", visit);
                }

                break;
            case JsonArray array:
                for (var i = 0; i < array.Count; i++)
                {
                    Walk(array[i], $"{pointer}/{i}", visit);
                }

                break;
        }
    }

    private static bool Resolve(JsonNode root, string reference)
    {
        var node = root;
        foreach (var raw in reference.TrimStart('#').Split('/', StringSplitOptions.RemoveEmptyEntries))
        {
            var part = raw.Replace("~1", "/", StringComparison.Ordinal).Replace("~0", "~", StringComparison.Ordinal);
            node = node switch
            {
                JsonObject obj => obj.TryGetPropertyValue(part, out var next) ? next : null,
                JsonArray array when int.TryParse(part, NumberStyles.None, CultureInfo.InvariantCulture, out var index) && index < array.Count => array[index],
                _ => null,
            };
            if (node is null)
            {
                return false;
            }
        }

        return true;
    }

    [GeneratedRegex(@"\|\s*`([a-z_]+)`\s*\|\s*(\d{3})\s*\|")]
    private static partial Regex ProblemRow();
}

/// <summary>Finds and reads the specification files.</summary>
internal static class SpecFiles
{
    private static readonly Regex Integer = new(@"^[-+]?[0-9]+$", RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex Float = new(@"^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$", RegexOptions.Compiled | RegexOptions.CultureInvariant);

    /// <summary>The repository root: the nearest folder above the test assembly that has IceScreenTouch.slnx.</summary>
    public static string RepositoryRoot()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
        {
            if (File.Exists(Path.Combine(dir.FullName, "IceScreenTouch.slnx")))
            {
                return dir.FullName;
            }
        }

        throw new InvalidOperationException("IceScreenTouch.slnx was not found above " + AppContext.BaseDirectory);
    }

    public static string YamlPath => Path.Combine(RepositoryRoot(), "docs", "api", "openapi.yaml");

    /// <summary>The routes the server registers, as <c>"GET /v1/status"</c>.</summary>
    public static IReadOnlyList<string> RegisteredRoutes()
    {
        var host = new FakeHost(new Microsoft.Extensions.Time.Testing.FakeTimeProvider());
        using var controller = new ApiController(host, () => true);
        return new ApiServer(controller, TestTokens.Main, port: 0).Routes;
    }

    /// <summary>The embedded document the server serves.</summary>
    public static JsonNode LoadEmbeddedJson()
    {
        using var stream = typeof(ApiServer).Assembly.GetManifestResourceStream("IceScreenTouch.Api.openapi.json")
            ?? throw new InvalidOperationException("the embedded openapi.json is missing");
        return JsonNode.Parse(stream)!;
    }

    /// <summary>
    /// The YAML specification as JSON nodes. A plain (unquoted) scalar gets the type YAML 1.2 gives it (null, boolean, number),
    /// a quoted one is a string; mapping keys must be strings (a duplicate key is an error). A value that YAML 1.1 (PyYAML, which
    /// the generator uses) types differently, such as <c>yes</c> or <c>on</c>, shows up as a difference to the JSON.
    /// </summary>
    public static JsonNode LoadYaml()
    {
        var stream = new YamlStream();
        using (var reader = new StreamReader(YamlPath))
        {
            stream.Load(reader);
        }

        return ToJson(stream.Documents[0].RootNode)!;
    }

    private static JsonNode? ToJson(YamlNode node)
    {
        switch (node)
        {
            case YamlMappingNode mapping:
                var obj = new JsonObject();
                foreach (var (key, value) in mapping.Children)
                {
                    if (key is not YamlScalarNode keyScalar)
                    {
                        throw new InvalidOperationException("a mapping key is not a scalar");
                    }

                    var name = keyScalar.Value ?? string.Empty;
                    if (keyScalar.Style == ScalarStyle.Plain && (Integer.IsMatch(name) || Float.IsMatch(name) || name is "true" or "false" or "null" or "~"))
                    {
                        throw new InvalidOperationException($"the mapping key {name} is not quoted (YAML would type it as a non-string)");
                    }

                    obj.Add(name, ToJson(value));
                }

                return obj;
            case YamlSequenceNode sequence:
                return new JsonArray([.. sequence.Children.Select(ToJson)]);
            case YamlScalarNode scalar:
                return ScalarToJson(scalar);
            default:
                throw new InvalidOperationException($"unsupported YAML node {node.GetType().Name}");
        }
    }

    private static JsonValue? ScalarToJson(YamlScalarNode scalar)
    {
        var text = scalar.Value ?? string.Empty;
        if (scalar.Style != ScalarStyle.Plain)
        {
            return JsonValue.Create(text);
        }

        if (text is "" or "~" or "null" or "Null" or "NULL")
        {
            return null;
        }

        if (text is "true" or "True" or "TRUE")
        {
            return JsonValue.Create(true);
        }

        if (text is "false" or "False" or "FALSE")
        {
            return JsonValue.Create(false);
        }

        if (Integer.IsMatch(text) && long.TryParse(text, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out var integer))
        {
            return JsonValue.Create(integer);
        }

        if (Float.IsMatch(text) && double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var number))
        {
            return JsonValue.Create(number);
        }

        return JsonValue.Create(text);
    }
}
